import gurobipy as gp
from gurobipy import GRB
warehouse_costs_source = '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP14/PotentialWarehouses_Costs.csv'
store_demands_source = '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP14/Stores_Demands.csv'
transport_cost_source = '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/UFLP_testing/UFLP14/TransportationCost.csv'
warehouses = []
f = {}
K = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == warehouse_costs_source:
        i = rec['values']['Warehouse (i)']
        warehouses.append(i)
        f[i] = float(rec['values']['Opening Cost (fi)'])
        K[i] = float(rec['values']['Capacity (units)'])
stores = []
d = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == store_demands_source:
        j = rec['values']['Store (j)']
        stores.append(j)
        d[j] = float(rec['values']['Demand (units, dj)'])
warehouse_keys = warehouses
store_keys = stores

def wkey_to_num(wkey):
    if wkey.startswith('W'):
        return str(int(wkey[1:]))
    return wkey
c = {i: {} for i in warehouse_keys}
transport_rows = [rec for rec in LEGACY_RECORDS if rec['source'] == transport_cost_source]
if len(transport_rows) != len(store_keys):
    raise ValueError('Transportation cost matrix row count does not match number of stores.')
for row in transport_rows:
    store_wkey = row['values']['Unnamed: 0']
    j = wkey_to_num(store_wkey)
    if j not in store_keys:
        raise ValueError(f'Store key {j} not found in store_keys.')
    for wcol in warehouse_keys:
        wcol_wkey = 'W' + wcol
        if wcol_wkey not in row['values']:
            raise ValueError(f'Warehouse column {wcol_wkey} missing in transportation cost row.')
        i = wcol
        c[i][j] = float(row['values'][wcol_wkey])
for i in warehouse_keys:
    for j in store_keys:
        if i not in c or j not in c[i]:
            raise ValueError(f'Missing transportation cost for warehouse {i}, store {j}.')
for i in warehouse_keys:
    if i not in f or i not in K:
        raise ValueError(f'Missing opening cost or capacity for warehouse {i}.')
for j in store_keys:
    if j not in d:
        raise ValueError(f'Missing demand for store {j}.')
m = gp.Model('UFLP_RAG')
y_vars = m.addVars(warehouse_keys, vtype=GRB.BINARY, name='')
x_vars = m.addVars(warehouse_keys, store_keys, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((f[i] * y_vars[i] for i in warehouse_keys)) + gp.quicksum((c[i][j] * x_vars[i, j] for i in warehouse_keys for j in store_keys)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[i, j] for i in warehouse_keys)) == d[j] for j in store_keys), name='')
m.addConstrs((gp.quicksum((x_vars[i, j] for j in store_keys)) <= K[i] * y_vars[i] for i in warehouse_keys), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')